<?php
declare(strict_types=1);
session_start();
header('Content-Type: application/json; charset=utf-8');
header('X-Content-Type-Options: nosniff');
header('Cache-Control: no-store');
function respond(int $status,array $body):void{http_response_code($status);echo json_encode($body,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
function payload():array{$d=json_decode(file_get_contents('php://input')?:'{}',true);return is_array($d)?$d:[];}
function db():PDO{static $pdo=null;if($pdo instanceof PDO)return $pdo;$dir=__DIR__.'/data';if(!is_dir($dir)&&!mkdir($dir,0750,true))respond(500,['ok'=>false,'error'=>'Не удалось создать каталог базы данных.']);if(!file_exists($dir.'/.htaccess'))@file_put_contents($dir.'/.htaccess',"Require all denied\\nDeny from all\\n");try{$pdo=new PDO('sqlite:'.$dir.'/converter.sqlite',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$pdo->exec('CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)');return $pdo;}catch(Throwable $e){respond(500,['ok'=>false,'error'=>'База данных недоступна. Проверь PDO_SQLITE на хостинге.']);}}
function public_user(array $r):array{return ['id'=>(int)$r['id'],'name'=>$r['name'],'email'=>$r['email']];}
$a=$_GET['action']??'';
if($a==='me'&&$_SERVER['REQUEST_METHOD']==='GET'){if(empty($_SESSION['user_id']))respond(200,['ok'=>true,'user'=>null]);$q=db()->prepare('SELECT id,name,email FROM users WHERE id=?');$q->execute([(int)$_SESSION['user_id']]);$u=$q->fetch();if(!$u){session_destroy();respond(200,['ok'=>true,'user'=>null]);}respond(200,['ok'=>true,'user'=>public_user($u)]);}
if($_SERVER['REQUEST_METHOD']!=='POST')respond(405,['ok'=>false,'error'=>'Метод не поддерживается.']);
$d=payload();
if($a==='logout'){$_SESSION=[];if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),'',time()-42000,$p['path'],$p['domain'],$p['secure'],$p['httponly']);}session_destroy();respond(200,['ok'=>true]);}
if($a==='register'){$name=trim((string)($d['name']??''));$email=strtolower(trim((string)($d['email']??'')));$pass=(string)($d['password']??'');$length=function_exists('mb_strlen')?mb_strlen($name):strlen($name);if($length<2||$length>40)respond(422,['ok'=>false,'error'=>'Имя должно содержать от 2 до 40 символов.']);if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($email)>190)respond(422,['ok'=>false,'error'=>'Укажи корректную электронную почту.']);if(strlen($pass)<8||strlen($pass)>128)respond(422,['ok'=>false,'error'=>'Пароль должен содержать от 8 до 128 символов.']);$pdo=db();$q=$pdo->prepare('SELECT id FROM users WHERE email=?');$q->execute([$email]);if($q->fetch())respond(409,['ok'=>false,'error'=>'Аккаунт с такой почтой уже существует.']);try{$q=$pdo->prepare('INSERT INTO users(name,email,password_hash) VALUES(?,?,?)');$q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);}catch(Throwable $e){respond(500,['ok'=>false,'error'=>'Не удалось создать аккаунт. Проверь базу данных.']);}session_regenerate_id(true);$_SESSION['user_id']=(int)$pdo->lastInsertId();respond(201,['ok'=>true,'user'=>['id'=>(int)$_SESSION['user_id'],'name'=>$name,'email'=>$email]]);}
if($a==='login'){$email=strtolower(trim((string)($d['email']??'')));$pass=(string)($d['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$pass==='')respond(422,['ok'=>false,'error'=>'Введи электронную почту и пароль.']);$q=db()->prepare('SELECT id,name,email,password_hash FROM users WHERE email=?');$q->execute([$email]);$r=$q->fetch();if(!$r||!password_verify($pass,$r['password_hash']))respond(401,['ok'=>false,'error'=>'Неверная почта или пароль.']);session_regenerate_id(true);$_SESSION['user_id']=(int)$r['id'];respond(200,['ok'=>true,'user'=>public_user($r)]);}
respond(404,['ok'=>false,'error'=>'Неизвестное действие.']);
